#include "stdlib/blas/ext/base/ndarray/ztril.h"
#include "stdlib/blas/ext/base/ztril.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/complex/float64/ctor.h"

/**
* Copies the lower triangular part of a double-precision complex floating-point matrix `A` to another matrix `B`.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a two-dimensional input ndarray corresponding to `A`.
*     -   a two-dimensional output ndarray corresponding to `B`.
*     -   a zero-dimensional int32 ndarray specifying the diagonal above which to ignore.
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_ztril( const struct ndarray *arrays[] ) {
	const struct ndarray *A = arrays[ 0 ];
	const struct ndarray *B = arrays[ 1 ];
	const struct ndarray *karr = arrays[ 2 ];

	const int64_t *shape = stdlib_ndarray_shape( A );
	const CBLAS_INT M = (CBLAS_INT)shape[ 0 ];
	const CBLAS_INT N = (CBLAS_INT)shape[ 1 ];

	const CBLAS_INT strideA1 = (CBLAS_INT)stdlib_ndarray_stride_elements( A, 0 );
	const CBLAS_INT strideA2 = (CBLAS_INT)stdlib_ndarray_stride_elements( A, 1 );
	const CBLAS_INT offsetA = (CBLAS_INT)stdlib_ndarray_offset_elements( A );
	const CBLAS_INT strideB1 = (CBLAS_INT)stdlib_ndarray_stride_elements( B, 0 );
	const CBLAS_INT strideB2 = (CBLAS_INT)stdlib_ndarray_stride_elements( B, 1 );
	const CBLAS_INT offsetB = (CBLAS_INT)stdlib_ndarray_offset_elements( B );

	// The typed getter assumes that the output type matches the ndarray dtype:
	if ( stdlib_ndarray_dtype( karr ) != STDLIB_NDARRAY_INT32 ) {
		return;
	}
	int32_t k_value;
	if ( stdlib_ndarray_get_int32( karr, NULL, &k_value ) != 0 ) {
		return;
	}
	const CBLAS_INT k = (CBLAS_INT)k_value;

	const stdlib_complex128_t *dataA = (const stdlib_complex128_t *)stdlib_ndarray_data( A );
	stdlib_complex128_t *dataB = (stdlib_complex128_t *)stdlib_ndarray_data( B );
	API_SUFFIX(stdlib_strided_ztril_ndarray)( M, N, k, dataA, strideA1, strideA2, offsetA, dataB, strideB1, strideB2, offsetB );
}
